// fix-trial-full-access-plan-comparison.cjs
// Implementa o novo modelo de trial: durante o periodo de teste gratuito,
// TODAS as funcionalidades ficam liberadas independente do plano escolhido
// no cadastro, EXCETO a configuracao de pagamentos (Asaas), que so fica
// disponivel com a assinatura ativa (pagando de verdade) — preserva o fluxo
// de pagamento ja definido antes.
//
// Quando o trial termina (status deixa de ser "trial"), as regras normais
// de bloqueio por plano (Solo/Equipe/Estudio) voltam a valer normalmente.
//
// Tambem corrige o array de planos exibido na tela de "Minha Assinatura"
// (app/admin/(tabs)/settings.tsx), que estava com precos desatualizados
// (49/89/149 em vez de 49,90/99,90/169,90) e lista de features incompleta/
// com erro (dizia "Ate 5 barbeiros" no plano Equipe, mas o limite real e 3).
//
// Arquivos alterados:
//   server/plan-features.ts        — nova funcao hasFeatureAccess(plan,
//                                     status, feature); novo FeatureKey
//                                     "asaas_settings"
//   server/routers.ts              — 3 chamadas assertFeature atualizadas
//                                     pra considerar o status; bloqueio de
//                                     asaas_settings adicionado em
//                                     setupSubAccount (que antes nao tinha
//                                     nenhum bloqueio); bpStatus completado
//                                     nos 2 pontos de login que faltavam
//   lib/plan-features.ts           — espelho client-side da mesma regra
//   lib/auth-context.tsx           — campo bpStatus adicionado ao tipo
//                                     AuthBarber
//   components/feature-gate.tsx    — usa hasFeatureAccess (considera
//                                     status), com mensagem propria pro
//                                     caso "asaas_settings"
//   app/onboarding/register.tsx    — define tenantPlan e bpStatus:"trial"
//                                     explicitamente logo apos o cadastro
//   app/admin/(tabs)/settings.tsx  — precos e features corrigidos no
//                                     array PLANS (usado no modal de
//                                     troca/escolha de plano)
//
// Uso:
//   node fix-trial-full-access-plan-comparison.cjs
//
// Seguranca: cada arquivo so e sobrescrito se o conteudo atual bater
// EXATAMENTE com o esperado (verificado por hash SHA-256) — evita
// sobrescrever qualquer mudanca que tenha sido feita nesses arquivos nesse
// meio tempo. Se algum arquivo nao bater, o script aborta ANTES de
// escrever qualquer coisa (nenhum arquivo fica parcialmente atualizado).

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const FILES = {
  "server/plan-features.ts": {
    expectedHash: "9d94262fa61b089b19fac4885d3c961154aaced0af5129d7ad109e4920bd7057",
    newContent: Buffer.from("", 'base64').toString('utf8'),
  },
  "server/routers.ts": {
    expectedHash: "3e2a99542595689887aae0d3ef9c6a9880adab35b2028ec5c64adff0fd28114a",
    newContent: Buffer.from("", 'base64').toString('utf8'),
  },
  "lib/plan-features.ts": {
    expectedHash: "fa277e833893a00ae68d51efc17c66aa36377927593b2756c5e0d651c6a3fd59",
    newContent: Buffer.from("", 'base64').toString('utf8'),
  },
  "lib/auth-context.tsx": {
    expectedHash: "2e4bd9ca7fd1bf15c0e99faca210758eeab47a4a0f82c745ca88cf6458262888",
    newContent: Buffer.from("", 'base64').toString('utf8'),
  },
  "components/feature-gate.tsx": {
    expectedHash: "52af1b3cefd1d1648856636be3ed52ec9d4a4422be770008cd1691245215ebb8",
    newContent: Buffer.from("", 'base64').toString('utf8'),
  },
  "app/onboarding/register.tsx": {
    expectedHash: "2ca31cde79fc36d156eb607671f9f2ff500f30b1ca63d6b1bfec72cb9f5421db",
    newContent: Buffer.from("", 'base64').toString('utf8'),
  },
  "app/admin/(tabs)/settings.tsx": {
    expectedHash: "5dd24252d6073aa930bf58a5e6c13d110d28ee90172789f1fca1abae24b0cba2",
    newContent: Buffer.from("", 'base64').toString('utf8'),
  },
};

try {
  // 1a passada: verifica TODOS os hashes antes de escrever qualquer coisa
  for (const [relPath, { expectedHash }] of Object.entries(FILES)) {
    const fullPath = path.join(__dirname, relPath);
    if (!fs.existsSync(fullPath)) {
      throw new Error(`Arquivo não encontrado: ${relPath}`);
    }
    const current = fs.readFileSync(fullPath, 'utf8');
    const currentHash = crypto.createHash('sha256').update(current, 'utf8').digest('hex');
    if (currentHash !== expectedHash) {
      throw new Error(
        `"${relPath}" não bate com o conteúdo esperado (hash diferente) — ` +
        `o arquivo pode já ter sido modificado. Abortando SEM escrever nada ` +
        `(nenhum dos ${Object.keys(FILES).length} arquivos foi tocado).`
      );
    }
  }

  // 2a passada: todos bateram, agora escreve todos
  for (const [relPath, { newContent }] of Object.entries(FILES)) {
    fs.writeFileSync(path.join(__dirname, relPath), newContent, 'utf8');
    console.log(`✅ ${relPath} atualizado.`);
  }

  console.log('');
  console.log('Próximos passos:');
  console.log('  1. git status');
  console.log('  2. git diff --stat   (deve mostrar os 7 arquivos)');
  console.log('  3. git add server/plan-features.ts server/routers.ts lib/plan-features.ts lib/auth-context.tsx components/feature-gate.tsx app/onboarding/register.tsx "app/admin/(tabs)/settings.tsx"');
  console.log('  4. git commit -m "feat: libera todas as funcionalidades durante o trial (exceto config. de pagamentos)"');
  console.log('  5. git push');
  console.log('  6. Testar: cadastrar um tenant novo, confirmar que Produtos/Cupons/Comissoes/Planos ficam liberados mesmo no plano Solo durante o trial, e que a config. do Asaas continua bloqueada até assinar');
} catch (err) {
  console.error('❌ Falha ao aplicar a alteração:');
  console.error(err.message);
  process.exit(1);
}
